insert into public.arc_collections
  (organization_id,title,slug,description,status,source,metadata)
select
  'f00ab7ef-e9be-467b-9e95-db8f753275c3'::uuid,
  title,
  slug,
  group_name || ' menüsündeki canlı ArvoCulture koleksiyonu.',
  'active',
  'shopify',
  jsonb_build_object(
    'source_kind','storefront_menu',
    'menu_group',group_name,
    'storefront_path',storefront_path,
    'storefront_url','https://arvoculture.com/collections/' || storefront_path
  )
from menu
on conflict (organization_id,slug) do update set
  title=excluded.title,
  description=excluded.description,
  status='active',
  source='shopify',
  metadata=excluded.metadata,
  updated_at=now();

delete from public.arc_collection_products cp
using public.arc_collections c
where cp.collection_id=c.id
  and c.organization_id='f00ab7ef-e9be-467b-9e95-db8f753275c3'
  and c.metadata->>'source_kind'='storefront_menu';

