rici-takviyeler","group_name":"Takviyeler","storefront_path":"bagisiklik-guclendirici-takviyeler","products":["lr-aloe-vera-jel-icecek-zencefil-limon-1000ml","lr-aloe-vera-jel-icecek-sivera-1000ml","lr-lifetakt-liver-support-karaciger","lr-lifetakt-pro-12-probiotic-probiyotik","reishi-plus","lifetakt-master-drink-red","lifetakt-master-drink-green"]},{"title":"Spor Takviyeleri","slug":"spor-takviyeleri","group_name":"Takviyeler","storefront_path":"spor-takviyeleri","products":["lifetakt-master-drink-red","lifetakt-master-drink-green"]}]'::jsonb)
    as x(title text, slug text, group_name text, storefront_path text, products jsonb)
),
members as (
  select m.slug as collection_slug, p.value#>>'{}' as product_slug, p.ordinality::int as position
  from menu m
  cross join lateral jsonb_array_elements(m.products) with ordinality p(value,ordinality)
)
insert into public.arc_collection_products
  (organization_id,collection_id,product_id,position)
select
  c.organization_id,c.id,pr.id,m.position
from members m
join public.arc_collections c
  on c.organization_id='f00ab7ef-e9be-467b-9e95-db8f753275c3'
 and c.slug=m.collection_slug
join public.arc_products pr
  on pr.organization_id=c.organization_id
 and pr.slug=m.product_slug
on conflict (collection_id,product_id) do update set position=excluded.position;
commit;
